import type Anthropic from "@anthropic-ai/sdk";
import type { GraphChange, GraphSnapshot } from "./graph.ts";
import type { SampleId } from "./samples/index.ts";
import type { ThreadId } from "./selection.ts";
import { type MessageIdx, projectLog, trimUnansweredTools } from "./thread.ts";
import type { Origin, ThreadTree } from "./threads.ts";
import type { Build } from "./view.ts";

export const VERSION = 1;

export type ThreadSnapshot = {
  id: ThreadId;
  origin: Origin | null;
  system: string;
  /** Held apart from `log` because `Thread` does: it is turn 0 of the wire
   * log and is never rendered, so restoring it as an ordinary turn would put
   * it in the transcript. */
  seed: string | Anthropic.ContentBlockParam[] | undefined;
  /** The committed turns after the seed. */
  log: Anthropic.MessageParam[];
  children: ThreadId[];
  activeChild: ThreadId | null;
  draft: string;
};

/** One finished graph update, keyed by the interaction that caused it.
 * Running updates are omitted, which is what makes them re-enqueue. */
export type UpdateSnapshot = {
  thread: ThreadId;
  index: MessageIdx;
  changes: ReadonlyArray<GraphChange>;
};

export type Snapshot = {
  version: number;
  sample: SampleId | undefined;
  threads: ThreadSnapshot[];
  nextThreadId: number;
  root: ThreadId;
  graph: GraphSnapshot;
  updates: UpdateSnapshot[];
  build: Build;
};

/** The tree, flattened. Logs are trimmed to stay API-valid, so a refresh
 * mid-tool-call cannot persist a call the model can never answer. */
export function threadSnapshots(tree: ThreadTree): ThreadSnapshot[] {
  return tree.nodes().map((node) => ({
    id: node.id,
    origin: node.origin,
    system: node.thread.systemPrompt,
    seed: node.thread.seed,
    log: trimUnansweredTools(node.thread.log),
    children: [...node.children],
    activeChild: node.activeChild,
    draft: node.draft,
  }));
}

export type InteractionAddress = { thread: ThreadId; index: MessageIdx };

/** Every user turn in the tree - the addresses a graph update is keyed by -
 * root first and then the remaining threads in id order, each in message
 * order, which is the order a rebuild has to replay them in.
 *
 * `sampleTurnCount` is how many of the root's interactions came from the
 * canned transcript; they are only in scope once a build has been asked for. */
export function interactionAddresses(
  threads: ReadonlyArray<ThreadSnapshot>,
  root: ThreadId,
  includeSampleTurns: boolean,
  sampleTurnCount: number,
): InteractionAddress[] {
  const ordered = [
    ...threads.filter((t) => t.id === root),
    ...threads.filter((t) => t.id !== root),
  ];
  const out: InteractionAddress[] = [];
  for (const thread of ordered) {
    const isRoot = thread.id === root;
    let seen = 0;
    projectLog(thread.log).forEach((message, i) => {
      if (message.type !== "text" || message.role !== "user") return;
      const sampleTurn = isRoot && seen < sampleTurnCount;
      seen++;
      if (sampleTurn && !includeSampleTurns) return;
      out.push({ thread: thread.id, index: i as MessageIdx });
    });
  }
  return out;
}

import { type Citation, parse, resolve } from "../citation.ts";
import {
  type GraphChange,
  type GraphEdge,
  type GraphNode,
  isNodeId,
  KnowledgeGraph,
  type NodeId,
} from "../graph.ts";
import { changesIn, readTools, writeTools } from "../graph-tools.ts";
import type {
  Chip,
  Citations,
  Msg as GraphMsg,
  Sidebar,
  Viewport,
} from "../graph-view.ts";
import { IDENTITY_VIEWPORT, panZoom } from "../graph-view.ts";
import { interactionAt } from "../interactions.ts";
import { layout, type Position } from "../layout.ts";
import { GRAPH_UPDATE_SYSTEM, graphUpdatePrompt } from "../prompt.ts";
import {
  type SampleId,
  selectedSample,
  selectSample,
} from "../samples/index.ts";
import { overlaps, type ThreadId } from "../selection.ts";
import { type Message, type MessageIdx, runThread, Thread } from "../thread.ts";
import { ThreadTree } from "../threads.ts";
import { PostRenderEventBus } from "../vamp.ts";
import {
  type AppEvent,
  AppView,
  type GraphUpdate,
  type Msg,
  type State,
  type Updates,
} from "../view.ts";

/** The editable fields of a node or edge: the id addresses it, so it is not
 * part of what the sidebar edits. */
function draftOf(node: GraphNode): Omit<GraphNode, "id">;
function draftOf(edge: GraphEdge): Omit<GraphEdge, "id">;
function draftOf<T extends { id: string }>(item: T): Omit<T, "id"> {
  const { id: _id, ...rest } = item;
  return rest;
}

/** What an update thread did, read off its own transcript: a call that never
 * finished parsing or came back an error changed nothing, so it reports
 * nothing. */
function changesOf(
  messages: ReadonlyArray<Message>,
): ReadonlyArray<GraphChange> {
  return messages.flatMap((m) =>
    m.type === "tool_use" && m.call.input && m.call.result?.status === "ok"
      ? [...changesIn(m.call.result.text)]
      : [],
  );
}

function connect(): WebSocket {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return new WebSocket(`${proto}//${window.location.host}/api/socket`);
}

/** Prototype 1: the task transcript, with learning threads hanging off the
 * passages the user picks out of it. */
export function mount(container: HTMLElement): void {
  // One socket for the whole app: every Thread adds its own
  // listener and drops frames whose requestId it does not own, so streams
  // interleave over the single connection.
  const socket = connect();
  // Scoped to the user, not to a thread: it outlives every thread in the tree
  // and is discarded only by a page load.
  const graph = new KnowledgeGraph();
  const tree = new ThreadTree(
    socket,
    new Thread(socket, { initialTurns: selectedSample()?.turns }),
    () => {
      refresh();
      view.sync(state);
    },
  );
  // The thread on the left. Moved only by the arrows.
  let focus = tree.root;
  let sidebar: Sidebar = { type: "closed" };
  // Pan and zoom live beside the sidebar rather than in the view: the view
  // holds no state of its own, and a rebuild of the graph must not recentre it.
  let viewport: Viewport = IDENTITY_VIEWPORT;
  // Graph updates run one at a time: two in flight would each be handed the
  // pre-update graph and mint rival nodes for the same concept. Appending to
  // this chain is the whole serialization.
  let updates: Promise<void> = Promise.resolve();
  // What each interaction's update is doing, keyed by its address. Derived from
  // the update thread's own tool calls, so it cannot disagree with what the
  // model actually did.
  const graphUpdates = new Map<string, GraphUpdate>();
  const address = (thread: ThreadId, index: MessageIdx) => `${thread}:${index}`;
  function updatesFor(thread: ThreadId): Updates {
    const out = new Map<number, GraphUpdate>();
    for (const [key, update] of graphUpdates) {
      const [id, index] = key.split(":");
      if (id === thread) out.set(Number(index), update);
    }
    return out;
  }
  // The layout is a few hundred iterations, and refresh() runs on every
  // keystroke, so it is recomputed only when the shape of the graph changes.
  let placement = new Map<NodeId, Position>();
  let placedFor = "";
  // Purely presentational, and per thread: which messages the user has
  // expanded past the collapsed height.
  const expanded = new Map<ThreadId, Set<number>>();
  function expandedFor(id: ThreadId): Set<number> {
    let set = expanded.get(id);
    if (!set) {
      set = new Set();
      expanded.set(id, set);
    }
    return set;
  }

  const state: State = {
    sample: selectedSample()?.id ?? "",
    messages: [],
    inFlight: false,
    draft: "",
    split: false,
    depth: 0,
    canDescend: false,
    thread: focus,
    marks: [],
    activeMark: null,
    anchor: null,
    tab: "threads",
    graph: {
      nodes: [],
      edges: [],
      viewport,
      sidebar,
      citations: { description: [], notes: [] },
    },
    build: { type: "idle" },
    query: "",
    expanded: new Set(),
    updates: new Map(),
    child: null,
  };

  /** Re-projects the tree onto the view's state. Everything but the fields the
   * user is editing is derived, so this runs after every dispatch. */
  /** The graph projected onto view state: positions from `layout`, and the
   * sidebar the user is editing. */
  function refreshGraph(): void {
    const nodes = graph.nodes;
    const edges = graph.edges;
    const shape = [
      ...nodes.map((n) => n.id),
      ...edges.map((e) => `${e.id}:${e.from}->${e.to}`),
    ].join(",");
    if (shape !== placedFor) {
      placement = layout(graph);
      placedFor = shape;
    }
    const at = (id: NodeId): Position =>
      placement.get(id) ?? { x: 0.5, y: 0.5 };
    state.graph = {
      nodes: nodes.map((n) => ({ ...n, pos: at(n.id) })),
      edges: edges.map((e) => ({ ...e, from_: at(e.from), to_: at(e.to) })),
      viewport,
      sidebar,
      citations: citationsOf(),
    };
  }

  /** The citations in the *saved* prose of whatever the sidebar has open. Read
   * off the graph rather than the draft: a half-typed address is not a
   * citation, and one that does not resolve against the tree is not either. */
  function citationsOf(): Citations {
    const chips = (text: string): Chip[] =>
      parse(text).flatMap((span) => {
        if (span.type !== "citation") return [];
        const quote = resolve(tree, span.citation);
        return quote === undefined ? [] : [{ citation: span.citation, quote }];
      });
    switch (sidebar.type) {
      case "closed":
        return { description: [], notes: [] };
      case "edge": {
        const edge = graph.edge(sidebar.id);
        return { description: chips(edge?.description ?? ""), notes: [] };
      }
      case "node": {
        const node = graph.node(sidebar.id);
        return {
          description: chips(node?.description ?? ""),
          notes: chips(node?.notes ?? ""),
        };
      }
    }
  }

  function refresh(): void {
    refreshGraph();
    const node = tree.get(focus);
    state.thread = focus;
    state.depth = state.split ? tree.path(focus).length : 0;
    state.canDescend = node.activeChild !== null;
    state.messages = node.thread.messages;
    state.inFlight = node.thread.inFlight;
    state.draft = node.draft;
    state.marks = tree.marks(focus);
    state.expanded = expandedFor(focus);
    state.updates = updatesFor(focus);
    state.activeMark = node.activeChild;
    const activeChild = node.activeChild;
    if (!activeChild) {
      state.child = null;
      return;
    }
    const child = tree.get(activeChild);
    state.child = {
      messages: child.thread.messages,
      inFlight: child.thread.inFlight,
      draft: child.draft,
      expanded: expandedFor(activeChild),
      updates: updatesFor(activeChild),
    };
  }

  function sync(): void {
    refresh();
    view.sync(state);
  }

  /** One detached thread per user interaction, writing straight into the graph
   * through its tools. Queued against every other update rather than run
   * concurrently, and never awaited by the user: the learning thread answers
   * them regardless, and a failure here is invisible outside the console. */
  function queueGraphUpdate(
    thread: ThreadId,
    index: MessageIdx,
  ): Promise<boolean> {
    const interaction = interactionAt(tree, thread, index);
    const key = address(thread, index);
    graphUpdates.set(key, { type: "running" });
    // The update thread's transcript, as of its last change: the chips are read
    // off the calls it actually made, not off a side channel.
    let transcript: ReadonlyArray<Message> = [];
    const done = updates
      .then(async () => {
        // Read inside the queued step, so this update sees the previous one's
        // writes rather than the graph as it stood when it was enqueued.
        const result = await runThread(socket, {
          system: GRAPH_UPDATE_SYSTEM,
          prompt: graphUpdatePrompt(interaction, graph.render()),
          tools: writeTools(graph),
          yieldSchema: "text",
          onChange: (messages) => {
            transcript = messages;
          },
        });
        if (result.status === "error") {
          console.error(result.error);
          return false;
        }
        return true;
      })
      .catch((e: unknown) => {
        console.error(e);
        return false;
      })
      .then((ok) => {
        graphUpdates.set(key, { type: "done", changes: changesOf(transcript) });
        sync();
        return ok;
      });
    updates = done.then(() => undefined);
    return done;
  }

  /** The sample's own turns: a loaded transcript is a session that happened
   * before this page existed, so no live update ever ran over it. Every turn
   * after these came from an interaction that updated the graph itself, so
   * enumerating once at mount is what keeps the build from double-counting. */
  const sampleInteractions: MessageIdx[] = tree
    .get(tree.root)
    .thread.messages.flatMap((m, i) =>
      m.role === "user" && m.type === "text" ? [i as MessageIdx] : [],
    );

  /** Walks the loaded sample's turns through the same queue the live updates
   * use, so an interaction mid-build interleaves rather than races. */
  function runBuild(): void {
    if (state.build.type !== "idle") return;
    const total = sampleInteractions.length;
    if (total === 0) return;
    state.build = { type: "running", done: 0, total, failed: 0 };
    void (async () => {
      for (const index of sampleInteractions) {
        const ok = await queueGraphUpdate(tree.root, index);
        const build = state.build;
        if (build.type !== "running") return;
        state.build = {
          type: "running",
          done: build.done + 1,
          total: build.total,
          failed: build.failed + (ok ? 0 : 1),
        };
        sync();
      }
      const build = state.build;
      state.build = {
        type: "done",
        failed: build.type === "running" ? build.failed : 0,
      };
      sync();
    })();
  }

  function send(id: ThreadId): void {
    const node = tree.get(id);
    const text = node.draft.trim();
    if (text === "" || node.thread.inFlight) return;
    node.draft = "";
    // Nothing is streaming while the thread is idle, so the turn lands at the
    // end of `messages` - which is its citable address.
    const index = node.thread.messages.length as MessageIdx;
    node.thread.send(text).then(undefined, (e: unknown) => {
      console.error(e);
    });
    void queueGraphUpdate(id, index);
  }

  /** A citation run forwards: focus the cited thread and put the cited message
   * in front of the user. Focusing a deep thread is just setting each
   * ancestor's `activeChild`, which is the same state a mark click sets, so
   * this introduces no second notion of focus. The scroll cannot happen here -
   * the pane is not showing that thread until after the sync - so it goes out
   * on the post-render bus. */
  function reveal(state: State, citation: Citation): void {
    const path = tree.path(citation.thread);
    path.forEach((id, i) => {
      const next = path[i + 1];
      if (next) tree.get(id).activeChild = next;
    });
    focus = citation.thread;
    state.split = path.length > 1;
    state.tab = "threads";
    state.anchor = null;
    state.query = "";
    bus.emit({ type: "transcript:reveal", index: citation.index });
  }

  /** The graph tab's own reducer. It writes to the graph and to `sidebar`;
   * everything the canvas shows is re-derived in refreshGraph(). */
  function updateGraph(msg: GraphMsg): void {
    switch (msg.type) {
      case "SELECT_NODE": {
        const node = graph.node(msg.id);
        if (!node) break;
        sidebar = {
          type: "node",
          id: node.id,
          draft: draftOf(node),
          error: null,
        };
        break;
      }
      case "SELECT_EDGE": {
        const edge = graph.edge(msg.id);
        if (!edge) break;
        sidebar = {
          type: "edge",
          id: edge.id,
          draft: draftOf(edge),
          error: null,
        };
        break;
      }
      case "CLOSE":
        sidebar = { type: "closed" };
        break;
      case "NODE_FIELD":
        if (sidebar.type === "node") sidebar.draft[msg.field] = msg.value;
        break;
      case "LEVEL_CHANGED":
        if (sidebar.type === "node") sidebar.draft.level = msg.level;
        break;
      case "EDGE_FIELD":
        if (sidebar.type === "edge") sidebar.draft[msg.field] = msg.value;
        break;
      case "SAVE": {
        if (sidebar.type === "closed") break;
        const result =
          sidebar.type === "node"
            ? graph.putNode({ id: sidebar.id, ...sidebar.draft })
            : graph.putEdge({ id: sidebar.id, ...sidebar.draft });
        // A rejected save keeps the draft, so the user's typing survives.
        sidebar.error = result.status === "error" ? result.error : null;
        break;
      }
      case "DELETE": {
        if (sidebar.type === "closed") break;
        if (sidebar.type === "node") graph.deleteNode(sidebar.id);
        else graph.deleteEdge(sidebar.id);
        sidebar = { type: "closed" };
        break;
      }
      case "PAN":
      case "ZOOM":
      case "RESET_VIEW":
        viewport = panZoom(viewport, msg);
        break;
    }
  }

  function update(state: State, msg: Msg): void {
    const node = tree.get(focus);
    switch (msg.type) {
      case "DRAFT_CHANGED":
        node.draft = msg.draft;
        break;
      case "SAMPLE_CHANGED":
        selectSample(msg.id === "" ? undefined : (msg.id as SampleId));
        break;
      case "TAB_CHANGED":
        state.tab = msg.tab;
        break;
      case "CHANGE_CLICKED":
        state.tab = "graph";
        updateGraph(
          isNodeId(msg.id)
            ? { type: "SELECT_NODE", id: msg.id }
            : { type: "SELECT_EDGE", id: msg.id },
        );
        break;
      case "GRAPH_MSG":
        if (msg.msg.type === "CITATION_CLICKED")
          reveal(state, msg.msg.citation);
        else updateGraph(msg.msg);
        break;
      case "SUBMIT":
        send(focus);
        break;
      case "BUILD":
        runBuild();
        break;
      case "GO_DEEPER": {
        if (!state.split) {
          state.split = true;
          break;
        }
        const child = node.activeChild;
        if (!child) break;
        focus = child;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "GO_BACK": {
        const parent = node.origin?.anchor.thread;
        if (parent === undefined) state.split = false;
        else focus = parent;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "TOGGLE_EXPANDED": {
        const set = expandedFor(focus);
        if (!set.delete(msg.index)) set.add(msg.index);
        break;
      }
      case "SELECTION_CHANGED":
        state.anchor = msg.anchor;
        node.activeChild = null;
        break;
      case "MARK_CLICKED":
        state.anchor = null;
        node.activeChild = msg.thread;
        break;
      case "LEARNING_MSG":
        switch (msg.msg.type) {
          case "ACTION": {
            const anchor = state.anchor;
            if (!anchor || overlaps(state.marks, anchor)) break;
            const id = tree.open(anchor, msg.msg.action, {
              tools: readTools(graph),
              graph: graph.render(),
            });
            state.anchor = null;
            state.query = "";
            void queueGraphUpdate(id, 0 as MessageIdx);
            tree
              .get(id)
              .thread.start()
              .then(undefined, (e: unknown) => {
                console.error(e);
              });
            break;
          }
          case "QUERY_CHANGED":
            state.query = msg.msg.query;
            break;
        }
        break;
      case "CHILD_MSG": {
        const activeChild = node.activeChild;
        if (!activeChild) break;
        switch (msg.msg.type) {
          case "DRAFT_CHANGED":
            tree.get(activeChild).draft = msg.msg.draft;
            break;
          case "SUBMIT":
            send(activeChild);
            break;
          case "TOGGLE_EXPANDED": {
            const set = expandedFor(activeChild);
            if (!set.delete(msg.msg.index)) set.add(msg.msg.index);
            break;
          }
          case "CHANGE_CLICKED":
            update(state, msg.msg);
            break;
        }
        break;
      }
    }
    refresh();
  }

  // Scroll and flash are the one thing that cannot live in a reducer or a
  // binding: they need the DOM to already reflect the new focus.
  const bus = new PostRenderEventBus<AppEvent>();

  let dispatching = false;
  function dispatch(msg: Msg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg);
    view.sync(state);
    bus.flush();
    dispatching = false;
  }

  // e2e specs seed a known graph through this handle rather than driving the
  // extraction thread first, so the sidebar cases stay deterministic.
  (window as unknown as { __graph?: KnowledgeGraph }).__graph = graph;

  refresh();
  const view = new AppView(container, dispatch, state, { bus });
}

import type Anthropic from "@anthropic-ai/sdk";
import type { ThreadSnapshot } from "./persistence.ts";
import {
  type Action,
  askTurn,
  contextSeed,
  LEARNING_SYSTEM,
} from "./prompt.ts";
import type { Anchor, Mark, ThreadId } from "./selection.ts";
import type { Tool, ToolName, TurnResult } from "./thread.ts";
import { type Socket, Thread } from "./thread.ts";

export type { Action };

/** `anchor.thread` is the parent, so the link upward is the highlight itself. */
export type Origin = { anchor: Anchor; action: Action };

/** What a child thread is given beyond its seed. */
export type ChildOpts = {
  tools?: Record<ToolName, Tool>;
  /** The rendered knowledge graph, injected into the seed of a top-level
   * learning thread. */
  graph?: string;
  yieldSchema?: Anthropic.Tool.InputSchema | "text";
};

export type TreeNode = {
  id: ThreadId;
  /** null only for the root task thread. */
  origin: Origin | null;
  thread: Thread;
  /** Creation order; each child's `origin.anchor` is its highlight. */
  children: ThreadId[];
  activeChild: ThreadId | null;
  draft: string;
};

/** The tree of threads. Every thread but the root was opened from a
 * passage of its parent, so a thread and the highlight over its parent are the
 * same edge seen from either end. Threads are never destroyed or reparented. */
export class ThreadTree {
  private readonly threads = new Map<ThreadId, TreeNode>();
  private nextId = 0;
  root: ThreadId;
  private readonly socket: Socket;
  /** Attached to every thread the tree owns, so a stream anywhere in the
   * tree re-syncs the app. */
  private readonly onChange: () => void;

  constructor(socket: Socket, root: Thread, onChange: () => void) {
    this.socket = socket;
    this.onChange = onChange;
    this.root = this.add(null, root);
  }

  get(id: ThreadId): TreeNode {
    const node = this.threads.get(id);
    if (!node) throw new Error(`unknown thread ${id}`);
    return node;
  }

  /** Seeds a child thread from the parent's own seed plus its transcript
   * up to `anchor`, links it in, and makes it the parent's active child. The
   * caller starts it: the tree does not own the request lifecycle. */
  open(anchor: Anchor, action: Action, opts: ChildOpts = {}): ThreadId {
    const parent = this.get(anchor.thread);
    const thread = new Thread(this.socket, {
      system: LEARNING_SYSTEM,
      seed: contextSeed(
        typeof parent.thread.seed === "string" ? parent.thread.seed : undefined,
        parent.thread.messages,
        anchor,
        opts.graph,
      ),
      initialTurns: [
        {
          role: "user",
          content: askTurn(anchor, parent.thread.messages, action),
        },
      ],
      tools: opts.tools,
      yieldSchema: opts.yieldSchema,
    });
    const id = this.add({ anchor, action }, thread);
    parent.children.push(id);
    parent.activeChild = id;
    return id;
  }

  /** What a child thread settled with, once it has yielded. The parent renders
   * threads it never awaited, so the settled value has to be readable here. */
  result(id: ThreadId): TurnResult | undefined {
    return this.get(id).thread.result;
  }

  /** The highlights to draw over `id`'s transcript: one per child. */
  marks(id: ThreadId): Mark[] {
    return this.get(id).children.map((child) => {
      const origin = this.get(child).origin;
      if (!origin) throw new Error("child thread without an origin");
      return { thread: child, anchor: origin.anchor };
    });
  }

  /** root -> id, for the depth indicator. */
  path(id: ThreadId): ThreadId[] {
    const out: ThreadId[] = [];
    let at: ThreadId | undefined = id;
    while (at) {
      out.unshift(at);
      at = this.get(at).origin?.anchor.thread;
    }
    return out;
  }

  /** The id counter, persisted so a restored tree cannot re-mint an id. */
  get nextThreadId(): number {
    return this.nextId;
  }

  /** Every node, in creation order. */
  nodes(): ReadonlyArray<TreeNode> {
    return [...this.threads.values()];
  }

  /** Rebuilds a tree from persisted snapshots rather than from a root thread.
   * `threadOf` mints the `Thread` for each snapshot, so the caller owns tool
   * wiring, which the snapshot deliberately does not carry. */
  static restore(
    socket: Socket,
    snapshots: ReadonlyArray<ThreadSnapshot>,
    root: ThreadId,
    nextId: number,
    onChange: () => void,
    threadOf: (snapshot: ThreadSnapshot) => Thread,
  ): ThreadTree {
    const rootSnapshot = snapshots.find((s) => s.id === root);
    if (!rootSnapshot) throw new Error(`no snapshot for root ${root}`);
    const tree = new ThreadTree(socket, threadOf(rootSnapshot), onChange);
    const rootThread = tree.get(tree.root).thread;
    tree.threads.clear();
    for (const snapshot of snapshots) {
      const thread = snapshot.id === root ? rootThread : threadOf(snapshot);
      tree.threads.set(snapshot.id, tree.node(snapshot, thread));
    }
    tree.root = root;
    tree.nextId = nextId;
    return tree;
  }

  private node(snapshot: ThreadSnapshot, thread: Thread): TreeNode {
    thread.onChange = this.onChange;
    return {
      id: snapshot.id,
      origin: snapshot.origin,
      thread,
      children: [...snapshot.children],
      activeChild: snapshot.activeChild,
      draft: snapshot.draft,
    };
  }

  private add(origin: Origin | null, thread: Thread): ThreadId {
    const id = `t${this.nextId++}` as ThreadId;
    thread.onChange = this.onChange;
    this.threads.set(id, {
      id,
      origin,
      thread,
      children: [],
      activeChild: null,
      draft: "",
    });
    return id;
  }
}

